import { MutantDetail, MutationReport } from "../domain/mutation-report.js";

export interface MutantKillScaffold {
  mutantId: string;
  filePath: string;
  mutatorName: string;
  originalCode: string;
  mutatedCode: string;
  suggestedTestScaffold: string;
}

export class ExecuteMutantKillUseCase {
  public execute(report: MutationReport, mutantId: string): MutantKillScaffold | null {
    if (!report.files) {
      return null;
    }

    for (const [filePath, fileResult] of Object.entries(report.files)) {
      if (!fileResult.mutants) continue;

      const mutant = fileResult.mutants.find((m) => m.id === mutantId);
      if (mutant) {
        return this.generateScaffold(filePath, fileResult.source, mutant);
      }
    }

    return null;
  }

  private generateScaffold(
    filePath: string,
    source: string,
    mutant: MutantDetail
  ): MutantKillScaffold {
    const originalCode = this.extractLine(source, mutant.location?.start.line);
    const mutatedCode = mutant.replacement || "/* unknown */";

    // Very simple heuristic to generate a test stub
    const moduleNameMatch = filePath.match(/([a-zA-Z0-9_-]+)\.ts$/);
    const moduleName = moduleNameMatch ? moduleNameMatch[1] : "UnknownModule";

    const suggestedTestScaffold = `
import { describe, it, expect } from "vitest";

// Scaffold to kill mutant ${mutant.id} in ${filePath}
// Original: ${originalCode.trim()}
// Mutated:  ${mutatedCode.trim()}
describe("${moduleName} Mutant Kill", () => {
  it("should kill mutant ${mutant.id} by failing when ${mutant.mutatorName} is applied", () => {
    // 1. Arrange: Set up the state to trigger the specific branch/logic.
    // 2. Act: Call the function or method.
    // 3. Assert: Verify the outcome is strictly tied to the original code, 
    //    so the mutant (${mutatedCode.trim()}) produces a test failure.
    expect(true).toBe(false); // TODO: implement
  });
});
`.trim();

    return {
      mutantId: mutant.id,
      filePath,
      mutatorName: mutant.mutatorName || "Unknown",
      originalCode,
      mutatedCode,
      suggestedTestScaffold,
    };
  }

  private extractLine(source: string, lineNumber?: number): string {
    if (lineNumber === undefined) return "/* line unknown */";
    const lines = source.split("\n");
    if (lineNumber < 1 || lineNumber > lines.length) return "/* line out of bounds */";
    return lines[lineNumber - 1];
  }
}

