import { describe, it, expect } from "vitest";
import { ExecuteMutantKillUseCase } from "./execute-mutant-kill.use-case.js";
import { MutationReport } from "../domain/mutation-report.js";

describe("ExecuteMutantKillUseCase", () => {
  it("should return null if report files are undefined", () => {
    const useCase = new ExecuteMutantKillUseCase();
    const report: MutationReport = {} as MutationReport;
    expect(useCase.execute(report, "1")).toBeNull();
  });

  it("should return null if mutant is not found", () => {
    const useCase = new ExecuteMutantKillUseCase();
    const report: MutationReport = {
      files: {
        "src/app.ts": {
          source: "const x = 1;\nconst y = 2;",
          mutants: [{ id: "2", status: "Survived" }]
        }
      }
    } as unknown as MutationReport;
    expect(useCase.execute(report, "1")).toBeNull();
  });

  it("should handle files with no mutants", () => {
    const useCase = new ExecuteMutantKillUseCase();
    const report: MutationReport = {
      files: {
        "src/empty.ts": { source: "const x = 1;" }
      }
    } as unknown as MutationReport;
    expect(useCase.execute(report, "1")).toBeNull();
  });

  it("should generate a scaffold for a valid mutant", () => {
    const useCase = new ExecuteMutantKillUseCase();
    const report: MutationReport = {
      files: {
        "src/app.ts": {
          source: "const x = 1;\nconst y = 2;",
          mutants: [
            {
              id: "1",
              status: "Survived",
              mutatorName: "ArithmeticOperator",
              replacement: "-",
              location: { start: { line: 2, column: 0 }, end: { line: 2, column: 1 } }
            }
          ]
        }
      }
    } as unknown as MutationReport;

    const result = useCase.execute(report, "1");
    expect(result).not.toBeNull();
    expect(result?.mutantId).toBe("1");
    expect(result?.filePath).toBe("src/app.ts");
    expect(result?.mutatorName).toBe("ArithmeticOperator");
    expect(result?.originalCode).toBe("const y = 2;");
    expect(result?.mutatedCode).toBe("-");
    expect(result?.suggestedTestScaffold).toContain("describe(\"app Mutant Kill\"");
    expect(result?.suggestedTestScaffold).toContain("should kill mutant 1");
  });

  it("should handle missing location, replacement, and mutatorName", () => {
    const useCase = new ExecuteMutantKillUseCase();
    const report: MutationReport = {
      files: {
        "src/unknown.ts": {
          source: "const x = 1;\nconst y = 2;",
          mutants: [
            { id: "1", status: "Survived" }
          ]
        }
      }
    } as unknown as MutationReport;

    const result = useCase.execute(report, "1");
    expect(result).not.toBeNull();
    expect(result?.mutatorName).toBe("Unknown");
    expect(result?.originalCode).toBe("/* line unknown */");
    expect(result?.mutatedCode).toBe("/* unknown */");
  });

  it("should handle out of bounds line numbers", () => {
    const useCase = new ExecuteMutantKillUseCase();
    const report: MutationReport = {
      files: {
        "src/test.ts": {
          source: "const x = 1;",
          mutants: [
            { id: "1", status: "Survived", location: { start: { line: 5, column: 0 }, end: { line: 5, column: 0 } } },
            { id: "2", status: "Survived", location: { start: { line: 0, column: 0 }, end: { line: 0, column: 0 } } }
          ]
        }
      }
    } as unknown as MutationReport;

    expect(useCase.execute(report, "1")?.originalCode).toBe("/* line out of bounds */");
    expect(useCase.execute(report, "2")?.originalCode).toBe("/* line out of bounds */");
  });

  it("should handle files without extensions nicely", () => {
    const useCase = new ExecuteMutantKillUseCase();
    const report: MutationReport = {
      files: {
        "Dockerfile": {
          source: "FROM node:18",
